// Verifies that successive decrements correctly drain the count to zero.
TEST(ArrayDbRecordArrayTest, DecrementSuccessivelyToZero) {
    RecordArray *array = RecordArrayCreate(4);
    ASSERT_NE(array, nullptr);

    RecordArraySetValueRemoteness(array, 0, kUndecided, 3);

    EXPECT_EQ(RecordArrayDecrementNumUndecidedChildren(array, 0), 3)
        << "First decrement should return 3.";
    EXPECT_EQ(RecordArrayDecrementNumUndecidedChildren(array, 0), 2)
        << "Second decrement should return 2.";
    EXPECT_EQ(RecordArrayDecrementNumUndecidedChildren(array, 0), 1)
        << "Third decrement should return 1.";
    EXPECT_EQ(RecordArrayDecrementNumUndecidedChildren(array, 0), 0)
        << "Fourth decrement should return 0 (count was already zero).";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 0), 0)
        << "Final count should be 0.";

    RecordArrayDestroy(array);
}

// Verifies that decrementing at one position does not affect others.
TEST(ArrayDbRecordArrayTest, DecrementDoesNotAffectOtherPositions) {
    constexpr int64_t kSize = 4;
    RecordArray *array = RecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    // Set all positions to kUndecided with distinct child counts.
    for (int64_t i = 0; i < kSize; ++i) {
        RecordArraySetValueRemoteness(array, i, kUndecided,
                                      static_cast<int>(i + 1));
    }

    // Decrement only position 1.
    RecordArrayDecrementNumUndecidedChildren(array, 1);

    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 0), 1)
        << "Position 0 should remain 1.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 1), 1)
        << "Position 1 should be decremented from 2 to 1.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 2), 3)
        << "Position 2 should remain 3.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 3), 4)
        << "Position 3 should remain 4.";

    RecordArrayDestroy(array);
}

