TEST(ArrayDbRecordArrayTest, ClearWhenAlreadyZero) {
    RecordArray *array = RecordArrayCreate(4);
    ASSERT_NE(array, nullptr);

    RecordArraySetValueRemoteness(array, 0, kUndecided, 0);

    int old_count = RecordArrayClearNumUndecidedChildren(array, 0);

    EXPECT_EQ(old_count, 0)
        << "Should return 0 when the count was already zero.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 0), 0)
        << "Count should remain 0.";

    RecordArrayDestroy(array);
}

