// Verifies that clearing at one position does not affect others.
TEST(ArrayDbRecordArrayTest, ClearDoesNotAffectOtherPositions) {
    constexpr int64_t kSize = 4;
    RecordArray *array = RecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    for (int64_t i = 0; i < kSize; ++i) {
        RecordArraySetValueRemoteness(array, i, kUndecided,
                                      static_cast<int>(i + 5));
    }

    RecordArrayClearNumUndecidedChildren(array, 1);

    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 0), 5)
        << "Position 0 should remain 5.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 1), 0)
        << "Position 1 should be cleared to 0.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 2), 7)
        << "Position 2 should remain 7.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 3), 8)
        << "Position 3 should remain 8.";

    RecordArrayDestroy(array);
}

