// Verifies that writing through GetData is observable through the typed API.
TEST(ArrayDbRecordArrayTest, WriteThroughGetDataIsReadable) {
    RecordArray *array = RecordArrayCreate(4);
    ASSERT_NE(array, nullptr);

    // Construct a known Record value manually and write it through the raw
    // pointer.
    Record expected_record =
        (static_cast<uint16_t>(kWin) << kRecordNumRemotenessBits) | 42;

    Record *data = static_cast<Record *>(RecordArrayGetData(array));
    data[1] = expected_record;

    EXPECT_EQ(RecordArrayGetValue(array, 1), kWin)
        << "Value written through raw pointer should be readable via "
           "GetValue.";
    EXPECT_EQ(RecordArrayGetRemoteness(array, 1), 42)
        << "Remoteness written through raw pointer should be readable via "
           "GetRemoteness.";

    RecordArrayDestroy(array);
}

