// ======================== Cross-function Integration ========================

// Verifies that a freshly created array has kUndecided values and zero
// remotenesses everywhere.
TEST(ArrayDbRecordArrayTest,
     ZeroInitializedArrayHasUndecidedValuesAndZeroRemoteness) {
    constexpr int64_t kSize = 16;
    RecordArray *array = RecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    for (int64_t i = 0; i < kSize; ++i) {
        EXPECT_EQ(RecordArrayGetValue(array, i), kUndecided)
            << "Position " << i << " should have value kUndecided.";
        EXPECT_EQ(RecordArrayGetRemoteness(array, i), 0)
            << "Position " << i << " should have remoteness 0.";
    }

    RecordArrayDestroy(array);
}

// Verifies the interplay between SetValueRemoteness and
// GetNumUndecidedChildren.
TEST(ArrayDbRecordArrayTest, SetValueRemotenessThenGetNumUndecidedChildren) {
    RecordArray *array = RecordArrayCreate(4);
    ASSERT_NE(array, nullptr);

    RecordArraySetValueRemoteness(array, 1, kUndecided, 3);

    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 1), 3)
        << "NumUndecidedChildren should match remoteness when value is "
           "kUndecided.";

    RecordArraySetValue(array, 1, kWin);

    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 1), 0)
        << "NumUndecidedChildren should be 0 once value is no longer "
           "kUndecided.";

    RecordArrayDestroy(array);
}

// Verifies that decrementing followed by clearing works correctly together.
TEST(ArrayDbRecordArrayTest, DecrementThenClear) {
    RecordArray *array = RecordArrayCreate(4);
    ASSERT_NE(array, nullptr);

    RecordArraySetValueRemoteness(array, 0, kUndecided, 5);

    int after_dec = RecordArrayDecrementNumUndecidedChildren(array, 0);
    EXPECT_EQ(after_dec, 5) << "Decrement should return the old count of 5.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 0), 4)
        << "Count should be 4 after one decrement.";

    int after_clear = RecordArrayClearNumUndecidedChildren(array, 0);
    EXPECT_EQ(after_clear, 4) << "Clear should return the old count of 4.";
    EXPECT_EQ(RecordArrayGetNumUndecidedChildren(array, 0), 0)
        << "Count should be 0 after clearing.";

    RecordArrayDestroy(array);
}

// Verifies that RecordArrayMaximize results are readable through the getters.
TEST(ArrayDbRecordArrayTest, MaximizeThenGetFields) {
    RecordArray *array = RecordArrayCreate(4);
    ASSERT_NE(array, nullptr);

    RecordArraySetValueRemoteness(array, 0, kLose, 0);
    RecordArrayMaximize(array, 0, kWin, 50, CompareByValueThenRemoteness);

    EXPECT_EQ(RecordArrayGetValue(array, 0), kWin)
        << "Value should be kWin after maximize.";
    EXPECT_EQ(RecordArrayGetRemoteness(array, 0), 50)
        << "Remoteness should be 50 after maximize.";

    RecordArrayDestroy(array);
}

// Verifies a round-trip set-and-get for every legal Value, holding remoteness
// constant to confirm field isolation.
TEST(ArrayDbRecordArrayTest, SetAllValuesRoundTrip) {
    constexpr int kFixedRemoteness = 99;
    const Value kAllValues[] = {kUndecided, kLose, kDraw, kTie, kWin};
    constexpr int64_t kSize = sizeof(kAllValues) / sizeof(kAllValues[0]);

    RecordArray *array = RecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    for (int64_t i = 0; i < kSize; ++i) {
        RecordArraySetValueRemoteness(array, i, kAllValues[i],
                                      kFixedRemoteness);
    }

    for (int64_t i = 0; i < kSize; ++i) {
        EXPECT_EQ(RecordArrayGetValue(array, i), kAllValues[i])
            << "Round-trip value mismatch at position " << i << ".";
        EXPECT_EQ(RecordArrayGetRemoteness(array, i), kFixedRemoteness)
            << "Remoteness should remain " << kFixedRemoteness
            << " at position " << i << ".";
    }

    RecordArrayDestroy(array);
}

// Verifies that different value-remoteness pairs at each position do not
// interfere with each other.
TEST(ArrayDbRecordArrayTest, MultiplePositionsIndependence) {
    constexpr int64_t kSize = 5;
    RecordArray *array = RecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    const Value values[] = {kWin, kLose, kDraw, kTie, kUndecided};
    const int remotenesses[] = {10, 0, 500, kRemotenessMax, 3};

    for (int64_t i = 0; i < kSize; ++i) {
        RecordArraySetValueRemoteness(array, i, values[i], remotenesses[i]);
    }

    for (int64_t i = 0; i < kSize; ++i) {
        EXPECT_EQ(RecordArrayGetValue(array, i), values[i])
            << "Value mismatch at position " << i << ".";
        EXPECT_EQ(RecordArrayGetRemoteness(array, i), remotenesses[i])
            << "Remoteness mismatch at position " << i << ".";
    }

    RecordArrayDestroy(array);
}

// Verifies that GetRawSize matches the actual data accessible through
// GetReadOnlyData by performing a memcpy and byte-by-byte comparison.
TEST(ArrayDbRecordArrayTest, GetRawSizeMatchesWrittenData) {
    constexpr int64_t kSize = 5;
    RecordArray *array = RecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    // Fill with distinct values to make the comparison meaningful.
    const Value values[] = {kWin, kLose, kDraw, kTie, kUndecided};
    const int remotenesses[] = {1, 2, 3, 4, 5};
    for (int64_t i = 0; i < kSize; ++i) {
        RecordArraySetValueRemoteness(array, i, values[i], remotenesses[i]);
    }

    size_t raw_size = RecordArrayGetRawSize(array);
    const void *data = RecordArrayGetReadOnlyData(array);

    // Copy the raw data and compare byte-by-byte.
    auto *copy = new unsigned char[raw_size];
    std::memcpy(copy, data, raw_size);

    EXPECT_EQ(std::memcmp(copy, data, raw_size), 0)
        << "Copied data should match the original byte-by-byte.";

    delete[] copy;
    RecordArrayDestroy(array);
}
